# bar diagram: annual sales of a company (Rs crore)
_BAR=[("2021",40),("2022",55),("2023",50),("2024",70),("2025",85)]
def _bar():
    s='<line x1="40" y1="170" x2="320" y2="170" stroke="currentColor"/><line x1="40" y1="20" x2="40" y2="170" stroke="currentColor"/>'
    for v in (20,40,60,80):
        y=170-v*1.6;s+='<line x1="36" y1="%.1f" x2="320" y2="%.1f" stroke="currentColor" stroke-opacity="0.15"/><text x="32" y="%.1f" text-anchor="end">%d</text>'%(y,y,y+4,v)
    for i,(yr,v) in enumerate(_BAR):
        x=55+i*53;h=v*1.6
        s+='<rect x="%d" y="%.1f" width="34" height="%.1f" fill="#2c6e8f"/><text x="%d" y="%.1f" text-anchor="middle" font-weight="700">%d</text><text x="%d" y="186" text-anchor="middle">%s</text>'%(x,170-h,h,x+17,170-h-5,v,x+17,yr)
    return '<svg viewBox="0 0 330 195" width="330" height="195" role="img" aria-label="bar diagram"><g font-family="sans-serif" font-size="12" fill="currentColor">'+s+'</g></svg>'
BAR=_bar()
